// Referee: independent per-tree existence solver for the hub theorem / D4 base cases.
// Rooted trees D on d vertices generated by Beyer-Hedetniemi level sequences.
// mode "hub": for each D find least m in 0..MMAX (within node limit) such that T(D,m) (m extra leaves at root)
//             has a growth placement with ROOT labelled 0 (README label 1); for every m below that, find a growth
//             placement of T(D,m) with any root.
// mode "deg4": only D with root degree >=4; root must be anchor with m=0.
// Every certificate is re-checked from README definition by check().
// usage: hubsolve_ref mode d part nparts [nodelimit]
#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64;
int n,m_;                 // n vertices, labels 0..n-1
int par[64];vector<int> ch[64];int prevSame[64];int shape[64];
int lab[64];bool placed[64];
u64 nodes,limitN;
vector<pair<int,int>> edges;
map<vector<int>,int> shapeId;
int computeShape(int v){
    vector<int> k;for(int c:ch[v])k.push_back(computeShape(c));
    sort(k.begin(),k.end());
    auto it=shapeId.find(k);int id;
    if(it==shapeId.end()){id=shapeId.size();shapeId[k]=id;}else id=it->second;
    return shape[v]=id;
}
void setup(){ // from par[], root 0
    for(int i=0;i<n;i++)ch[i].clear();
    for(int i=1;i<n;i++)ch[par[i]].push_back(i);
    computeShape(0);
    for(int v=0;v<n;v++){
        auto&c=ch[v];
        for(size_t i=0;i<c.size();i++){prevSame[c[i]]=-1;for(int j=(int)i-1;j>=0;j--)if(shape[c[j]]==shape[c[i]]){prevSame[c[i]]=c[j];break;}}
    }
    prevSame[0]=-1;
}
int front[64];int nf;int svar=0; // bit0: try minus sign first, bit1: reverse frontier order
bool dfs(int k,u64 used){
    if(k==0)return true;
    if(++nodes>limitN)return false;
    int M=n-1;
    // snapshot frontier
    int loc[64];int c=nf;memcpy(loc,front,sizeof(int)*nf);
    for(int ii=0;ii<c;ii++){
        int i=(svar&2)?c-1-ii:ii;
        int u=loc[i];int pl=lab[par[u]];
        for(int s0=0;s0<2;s0++){
            int s=s0^(svar&1);
            int x=s?pl-k:pl+k;
            if(x<0||x>M||(used>>x&1))continue;
            lab[u]=x;placed[u]=true;
            // new frontier: remove u, add eligible children of u, add next same-shape sibling
            nf=0;for(int j=0;j<c;j++)if(j!=i)front[nf++]=loc[j];
            for(int w:ch[u])if(prevSame[w]<0)front[nf++]=w;
            for(int w:ch[par[u]])if(prevSame[w]==u)front[nf++]=w;
            if(dfs(k-1,used|(1ULL<<x)))return true;
            placed[u]=false;
            if(nodes>limitN)return false;
        }
    }
    nf=c;memcpy(front,loc,sizeof(int)*c);
    return false;
}
bool check(int root){ // README definition, independent of the search
    int M=n-1;vector<int> seenL(n,0);
    for(int v=0;v<n;v++){if(lab[v]<0||lab[v]>M||seenL[lab[v]])return false;seenL[lab[v]]=1;}
    if(root>=0&&lab[root]!=0)return false;
    vector<int> byLen(n,-1);
    for(int v=1;v<n;v++){int L=abs(lab[v]-lab[par[v]]);if(L<1||L>M||byLen[L]>=0)return false;byLen[L]=v;}
    // brackets of length >=k connected for every k: longest first, exactly one foot already used
    vector<int> usedL(n,0);
    for(int L=M;L>=1;L--){int v=byLen[L];int a=lab[v],b=lab[par[v]];
        if(L==M){usedL[a]=usedL[b]=1;continue;}
        if(usedL[a]==usedL[b])return false;usedL[a]=usedL[b]=1;}
    return true;
}
bool solveRoot0(){ // tree in par[] rooted at 0, root label 0
    setup();
    for(int i=0;i<n;i++)placed[i]=false;
    lab[0]=0;placed[0]=true;nf=0;
    for(int w:ch[0])if(prevSame[w]<0)front[nf++]=w;
    nodes=0;
    if(n==1)return true;
    if(!dfs(n-1,1ULL))return false;
    if(!check(0)){fprintf(stderr,"CHECK FAILED\n");exit(2);}
    return true;
}
// reroot helper: given base parent array bp (root 0) on n vertices, reroot at r into par[] with relabelling r->0
int bp[64];
void reroot(int r){
    vector<vector<int>> adj(n);for(int i=1;i<n;i++){adj[i].push_back(bp[i]);adj[bp[i]].push_back(i);}
    vector<int> id(n,-1);vector<int> q;q.push_back(r);id[r]=0;par[0]=-1;int cnt=1;
    for(size_t h=0;h<q.size();h++){int v=q[h];for(int u:adj[v])if(id[u]<0){id[u]=cnt++;par[id[u]]=id[v];q.push_back(u);}}
}
int main(int argc,char**argv){
    string mode=argv[1];int d=atoi(argv[2]);int part=atoi(argv[3]),nparts=atoi(argv[4]);
    u64 baseLimit=argc>5?atoll(argv[5]):200000;
    int MMAX=3;
    vector<int> L(d+1);for(int i=1;i<=d;i++)L[i]=i;
    u64 idx=0,tested=0;map<int,u64> hist;u64 unresolved=0,smallChecked=0,smallFail=0,maxnodes=0;
    while(true){
        if((int)(idx%nparts)==part){
            // parent array of D
            vector<int> dp(d);{vector<int> last(d+2,-1);for(int i=1;i<=d;i++){dp[i-1]=L[i]==1?-1:last[L[i]-1];last[L[i]]=i-1;}}
            int rootdeg=0;for(int i=1;i<d;i++)if(dp[i]==0)rootdeg++;
            if(mode=="deg4"){
                if(rootdeg>=4){
                    tested++;n=d;for(int i=0;i<d;i++)par[i]=dp[i];
                    bool ok=false;
                    for(u64 lim=baseLimit;lim<=baseLimit*100000ULL&&!ok;lim*=100)for(svar=0;svar<4&&!ok;svar++){limitN=lim;ok=solveRoot0();}
                    svar=0;
                    maxnodes=max(maxnodes,nodes);
                    if(!ok){unresolved++;printf("UNRESOLVED deg4 d=%d levels:",d);for(int i=1;i<=d;i++)printf(" %d",L[i]);printf("\n");}
                }
            }else{
                tested++;
                int m0=-1;
                for(u64 lim=baseLimit;lim<=baseLimit*10000ULL&&m0<0;lim*=100){
                    for(int mm=0;mm<=MMAX&&m0<0;mm++){
                        n=d+mm;for(int i=0;i<d;i++)par[i]=dp[i];for(int i=d;i<n;i++)par[i]=0;
                        limitN=lim;if(solveRoot0())m0=mm;
                    }
                }
                if(m0<0){unresolved++;printf("UNRESOLVED hub d=%d levels:",d);for(int i=1;i<=d;i++)printf(" %d",L[i]);printf("\n");}
                else{
                    hist[m0]++;
                    for(int mm=0;mm<m0;mm++){ // members below first success: any root
                        n=d+mm;for(int i=0;i<d;i++)bp[i]=dp[i];for(int i=d;i<n;i++)bp[i]=0;
                        smallChecked++;bool ok=false;
                        for(u64 lim=baseLimit;lim<=baseLimit*10000ULL&&!ok;lim*=100)
                            for(int r=0;r<n&&!ok;r++){reroot(r);limitN=lim;if(solveRoot0())ok=true;}
                        if(!ok){smallFail++;printf("NO-GROWTH-FOUND d=%d m=%d levels:",d,mm);for(int i=1;i<=d;i++)printf(" %d",L[i]);printf("\n");}
                    }
                }
            }
        }
        idx++;
        // successor
        int p=d;while(p>=1&&L[p]<=2)p--;
        if(p<1)break;
        int q=p-1;while(L[q]!=L[p]-1)q--;
        for(int i=p;i<=d;i++)L[i]=L[i-(p-q)];
    }
    printf("mode=%s d=%d part=%d/%d rooted trees total=%llu tested=%llu",mode.c_str(),d,part,nparts,idx,tested);
    if(mode=="hub"){printf(" first-found m0 hist:");for(auto&kv:hist)printf(" %d:%llu",kv.first,kv.second);printf(" unresolved=%llu smaller members checked=%llu failing=%llu\n",unresolved,smallChecked,smallFail);}
    else printf(" root-not-anchor-found=%llu maxnodes(last)=%llu\n",unresolved,maxnodes);
}
